INSERT INTO public.questoes (id, material_id, enunciado, referencia, comentario_professor, ordem, publicado) VALUES
('bb022e9e-95f9-4279-841f-1d2e1794d801', 'cdf9edb2-54fc-412a-abfe-1fc8bd769df8', 'Considerando o disposto no art. 12 da Constituição Federal, assinale a alternativa que descreve corretamente quem é brasileiro nato.', 'Fundação Universidade Empresa de Tecnologia e Ciências- FUNDATEC 2026 / Prefeitura de Araquari - SC / Guarda Municipal / Questão: 39', 'Jorge se enquadra no art. 12, I, "b", da CF: "são brasileiros natos os nascidos no estrangeiro, de pai brasileiro ou de mãe brasileira, desde que qualquer deles esteja a serviço da República Federativa do Brasil". Não importa registro posterior nesse caso, pois o critério é o serviço público no exterior. José (a) não é nato, pois seus pais estavam a serviço de país estrangeiro (Portugal), não do Brasil. Juca (c) não preencheu nenhuma das condições de nato do art. 12, I, "c" (nem registro, nem residência com opção). Josias (d) e Júlio (e) descrevem hipóteses de naturalização, não de nacionalidade nata.', 1, true),
('46ae322f-d9d7-406c-ba42-fa34937309e0', 'cdf9edb2-54fc-412a-abfe-1fc8bd769df8', 'Juan Carlos chegou ao Brasil como um jovem estrangeiro, fascinado pela cultura e pelas oportunidades que o país oferecia. Rapidamente, ele se apaixonou pela nação e decidiu fazer dela sua casa. Sempre interessado em política e com um forte desejo de fazer a diferença, Juan decidiu que queria se tornar _____________. Ele acreditava que poderia contribuir para o país de maneira significativa, trazendo inovação e crescimento. No entanto, ao estudar a Constituição Brasileira, Juan descobriu que o cargo tão sonhado era privativo de brasileiro nato. Assinale a alternativa que preenche corretamente a lacuna do trecho acima.', 'Fundação Universidade Empresa de Tecnologia e Ciências- FUNDATEC 2024 / Prefeitura de Arroio do Sal - RS / Auxiliar de Farmácia / Questão: 23', 'Presidente da República é cargo privativo de brasileiro nato (art. 12, §3º, I). Governador, prefeito, juiz estadual e defensor público não estão sujeitos a essa restrição constitucional.', 2, true),
('e710567a-83ce-4096-9b24-6ea3f888cf61', 'cdf9edb2-54fc-412a-abfe-1fc8bd769df8', 'De acordo com a Constituição Federal, o Brasil possui quatro símbolos nacionais. Assinale a alternativa que NÃO apresenta um símbolo oficial do Brasil.', 'Fundação Universidade Empresa de Tecnologia e Ciências- FUNDATEC 2024 / Prefeitura de Ibirapuitã - RS / Motorista / Questão: 29', 'Os quatro símbolos do art. 13, §1º, são bandeira, hino, armas e selo. "Padroeira" (referência religiosa) não integra o rol constitucional.', 3, true),
('50b90870-3186-4ab4-bb53-ad6c6ed37d6c', 'cdf9edb2-54fc-412a-abfe-1fc8bd769df8', 'Nos termos da Constituição Federal do Brasil, a lei não poderá estabelecer distinção entre brasileiros natos e naturalizados, salvo nos casos previstos na própria Constituição. Nesse sentido, são privativos de brasileiros natos os cargos de, EXCETO:', 'Fundação Universidade Empresa de Tecnologia e Ciências- FUNDATEC 2023 / Prefeitura de Faxinal do Soturno Prefeitura - RS / Auxiliar de Consultório Dentário / Questão: 22', 'Prefeito Municipal não consta do rol taxativo do art. 12, §3º, podendo ser ocupado por naturalizado. Todos os demais (Presidente, Vice-Presidente, Presidente do Senado e carreira diplomática) são privativos de nato.', 4, true),
('cb325ae1-20cf-4e2c-bf2b-2fbff24f94fe', 'cdf9edb2-54fc-412a-abfe-1fc8bd769df8', 'Conforme a Constituição Federal, o idioma oficial do Brasil é a língua:', 'Fundação Universidade Empresa de Tecnologia e Ciências- FUNDATEC 2023 / Prefeitura de Boa Vista do Buricá - RS / Motorista de Veículos Pesados / Questão: 23', 'Art. 13, caput: idioma oficial é a língua portuguesa.', 5, true),
('f10143a7-4f3d-46eb-9944-477500f8cbd9', 'cdf9edb2-54fc-412a-abfe-1fc8bd769df8', 'NÃO é cargo privativo de brasileiro nato:', 'Fundação Universidade Empresa de Tecnologia e Ciências- FUNDATEC 2023 / Instituto Federal Catarinense IFC - BR / Professor de Ensino Básico, Técnico e Tecnológico - Área: Direito / Questão: 29', '"Servidor público" é categoria genérica que não consta do rol taxativo do art. 12, §3º, podendo ser exercida por naturalizados. Os demais cargos são expressamente privativos de nato.', 6, true),
('94a076da-c3c4-4c78-bb80-63f15be6cfe6', 'cdf9edb2-54fc-412a-abfe-1fc8bd769df8', 'Paulo e Moema vieram da Rússia para o Brasil e ela estava grávida, tiveram, em solo brasileiro, uma filha a qual recebeu o nome de Maria. De acordo com a Constituição Federal do Brasil, são considerados brasileiros natos os nascidos na República Federativa do Brasil, ainda que de países estrangeiros, desde que estes:', 'Fundação Universidade Empresa de Tecnologia e Ciências- FUNDATEC 2020 / Companhia Municipal de Urbanismo de Novo Hamburgo COMUR - RS / Auxiliar Administrativo / Questão: 17', 'É a condição literal do art. 12, I, "a": nascidos no Brasil são natos, ainda que filhos de estrangeiros, "desde que estes não estejam a serviço de seu país". Como Paulo e Moema estavam apenas em território brasileiro sem vínculo funcional com a Rússia, Maria é brasileira nata.', 7, true);
